The evidence points to one root cause: a network fault on the seat → order-other connection. It cascades up through travel2, route-plan and travel-plan to the dashboard. I'm writing the answer now.

```json
{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "network_partition",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, sum(CASE WHEN duration > 1e9 THEN 1 ELSE 0 END) over_1s, approx_quantile(duration/1e6, 0.5) p50_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY 1,2,3", "claim": "Seat's outgoing POST client spans take about 131 s at p50 in the abnormal window, against about 5 ms in normal."},
        {"kind": "trace", "sql": "SELECT count(*) n_timeouts_no_child FROM abnormal_traces c WHERE c.service_name='ts-seat-service' AND c.attr_span_kind='Client' AND c.span_name='POST' AND c.duration > 1e9 AND NOT EXISTS (SELECT 1 FROM abnormal_traces ch WHERE ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id)", "claim": "Sixteen of seat's POST calls time out with no child span, so the callee never handled them."},
        {"kind": "log", "sql": "SELECT service_name, level, message FROM abnormal_logs WHERE service_name='ts-seat-service' AND level='SEVERE' LIMIT 3", "claim": "Seat logs 'Connection timed out' on POST to ts-order-other-service /orderOther/tickets."},
        {"kind": "trace", "sql": "SELECT count(*) n_server_tickets FROM abnormal_traces WHERE service_name='ts-order-other-service' AND attr_span_kind='Server' AND span_name LIKE '%orderOther/tickets%'", "claim": "Normal period had about 1268 order-other /tickets server spans; abnormal period has none."},
        {"kind": "metric", "sql": "SELECT metric, attr_source, attr_destination, sum(value) total FROM abnormal_metrics_sum WHERE metric IN ('hubble_tcp_flags_total','hubble_flows_processed_total') AND attr_source LIKE '%seat-service%' AND attr_destination LIKE '%order-other%' GROUP BY ALL", "claim": "Hubble flows and TCP flags on seat to order-other rise (SYN retries) while order-other serves no tickets."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-seat-service", "to": "ts-travel2-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) p50_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.service_name='ts-travel2-service' AND ch.service_name='ts-seat-service' GROUP BY 1,2", "claim": "Travel2's POST calls to seat run about 130 s and return 500 errors in the abnormal window."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, ch.service_name callee, c.attr_http_response_status_code st, count(*) n, approx_quantile(c.duration/1e6,0.5) p50_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.service_name='ts-route-plan-service' AND ch.service_name='ts-travel2-service' GROUP BY 1,2,3", "claim": "Route-plan's calls to travel2 return 500 after about 131 s in the abnormal window."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) p50_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND ch.service_name='ts-route-plan-service' GROUP BY 1,2", "claim": "Travel-plan's calls to route-plan take about 160 s and fail with errors in the abnormal window."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms, avg(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) err FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "Travel-plan's user-facing server spans show p95 of about 158-176 s and error shares of 0.5-1.0 in the abnormal window."}]},
    {"from": "ts-travel2-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, avg(CASE WHEN ch.attr_status_code='Error' THEN 1 ELSE 0 END) err, approx_quantile(ch.duration/1e6,0.95) p95_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.service_name='ts-ui-dashboard' AND ch.service_name='ts-travel2-service' GROUP BY 1,2", "claim": "Dashboard's calls to travel2 show about 0.67 error share and p95 in the 150 s range."}]}
  ]
}
